import{_ as a,o as t,c as l,a4 as d}from"./chunks/framework.CAgiNEKA.js";const c=JSON.parse('{"title":"Claude Fable 5 是什么？","description":"","frontmatter":{"title":"Claude Fable 5 是什么？","date":"2026-06-11T00:00:00.000Z","category":"AI 知识分享","tags":["Claude Fable 5","Claude Mythos 5","Anthropic","模型解读"]},"headers":[],"relativePath":"ai-knowledge/claude-fable-5-explained.md","filePath":"ai-knowledge/claude-fable-5-explained.md","lastUpdated":null}'),i={name:"ai-knowledge/claude-fable-5-explained.md"};function n(r,e,o,s,p,u){return t(),l("div",null,[...e[0]||(e[0]=[d('<h1 id="claude-fable-5-是什么" tabindex="-1">Claude Fable 5 是什么？ <a class="header-anchor" href="#claude-fable-5-是什么" aria-label="Permalink to &quot;Claude Fable 5 是什么？&quot;">​</a></h1><p>Claude Fable 5 是 Anthropic 在 2026 年 6 月 9 日发布的新一代 Claude 模型，也是目前 Anthropic 面向普通用户和企业客户开放的最高能力模型之一。</p><p>简单理解：<strong>Fable 5 是 Anthropic 把 Mythos 级能力做了安全限制后，对外开放的通用版本</strong>。它面向复杂推理、长周期 Agent 任务、代码工程、知识工作和多步骤研究场景。</p><h2 id="一句话解释" tabindex="-1">一句话解释 <a class="header-anchor" href="#一句话解释" aria-label="Permalink to &quot;一句话解释&quot;">​</a></h2><p>Claude Fable 5 可以看作是：</p><blockquote><p>更强的 Claude Agent 模型，适合长任务、复杂代码、深度推理，但在网络安全、生物等敏感领域有更严格的安全限制。</p></blockquote><h2 id="和-claude-mythos-5-有什么关系" tabindex="-1">和 Claude Mythos 5 有什么关系？ <a class="header-anchor" href="#和-claude-mythos-5-有什么关系" aria-label="Permalink to &quot;和 Claude Mythos 5 有什么关系？&quot;">​</a></h2><p>Anthropic 同时发布了 Claude Fable 5 和 Claude Mythos 5。</p><p>两者能力接近，但开放范围不同：</p><table tabindex="0"><thead><tr><th>模型</th><th>开放情况</th><th>适合谁</th></tr></thead><tbody><tr><td>Claude Fable 5</td><td>普通可用</td><td>大多数开发者、企业、Claude API 用户</td></tr><tr><td>Claude Mythos 5</td><td>限定开放</td><td>受邀客户、可信合作方、特殊安全研究场景</td></tr></tbody></table><p>Anthropic 官方说明，Claude Fable 5 是和 Mythos 5 同底层能力的模型，但加入了更强的安全分类器和防护机制；Mythos 5 则主要面向受控访问项目。</p><h2 id="fable-5-强在哪里" tabindex="-1">Fable 5 强在哪里？ <a class="header-anchor" href="#fable-5-强在哪里" aria-label="Permalink to &quot;Fable 5 强在哪里？&quot;">​</a></h2><p>根据 Anthropic 官方介绍，Claude Fable 5 的重点能力包括：</p><ol><li><p><strong>长周期 Agent 任务</strong> 适合 Claude Code、自动化工程、复杂项目拆解、多轮工具调用等任务。</p></li><li><p><strong>复杂代码与工程能力</strong> 官方和早期客户反馈都强调，它在长时间编码、重构、多步骤工程任务上比上一代更稳定。</p></li><li><p><strong>1M 上下文窗口</strong> Claude Fable 5 默认支持 100 万 token 上下文，适合处理大型代码库、长文档、复杂资料包。</p></li><li><p><strong>最高 128k 输出</strong> 单次请求最高可输出 128k token，适合长报告、长代码、完整方案类任务。</p></li><li><p><strong>Always-on Adaptive Thinking</strong> Fable 5 默认开启自适应思考，不再支持关闭 thinking。开发者需要用新的 effort 参数控制思考深度。</p></li></ol><h2 id="模型-id-是什么" tabindex="-1">模型 ID 是什么？ <a class="header-anchor" href="#模型-id-是什么" aria-label="Permalink to &quot;模型 ID 是什么？&quot;">​</a></h2><p>Claude API 中的模型 ID 是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude-fable-5</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在 AWS Bedrock 中，对应 ID 是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>anthropic.claude-fable-5</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Vertex AI 中也使用：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude-fable-5</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="价格是多少" tabindex="-1">价格是多少？ <a class="header-anchor" href="#价格是多少" aria-label="Permalink to &quot;价格是多少？&quot;">​</a></h2><p>Anthropic 官方价格为：</p><table tabindex="0"><thead><tr><th>项目</th><th>价格</th></tr></thead><tbody><tr><td>输入</td><td>$10 / 1M tokens</td></tr><tr><td>输出</td><td>$50 / 1M tokens</td></tr><tr><td>5 分钟缓存写入</td><td>$12.50 / 1M tokens</td></tr><tr><td>1 小时缓存写入</td><td>$20 / 1M tokens</td></tr><tr><td>缓存命中</td><td>$1 / 1M tokens</td></tr></tbody></table><p>这个价格高于 Claude Opus 4.8。Fable 5 更适合高价值复杂任务，不适合所有请求都默认使用。</p><h2 id="为什么有人说-fable-5-更-保守" tabindex="-1">为什么有人说 Fable 5 更“保守”？ <a class="header-anchor" href="#为什么有人说-fable-5-更-保守" aria-label="Permalink to &quot;为什么有人说 Fable 5 更“保守”？&quot;">​</a></h2><p>因为 Claude Fable 5 加了更严格的安全分类器。</p><p>当请求触发安全限制时，API 不一定返回普通错误，而可能返回：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stop_reason: &quot;refusal&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>也就是说，这类请求会被模型拒绝，或者通过 fallback 机制切换到其他 Claude 模型。</p><p>官方特别提到，Fable 5 在网络安全、生物等敏感领域会更谨慎，部分请求可能会被路由到 Claude Opus 4.8 或直接拒绝。</p><h2 id="对开发者有什么影响" tabindex="-1">对开发者有什么影响？ <a class="header-anchor" href="#对开发者有什么影响" aria-label="Permalink to &quot;对开发者有什么影响？&quot;">​</a></h2><p>如果你要在应用里接入 Claude Fable 5，需要注意：</p><ol><li><p><strong>要处理 refusal</strong> 不要只按普通成功回答处理，要识别 <code>stop_reason: &quot;refusal&quot;</code>。</p></li><li><p><strong>要准备 fallback</strong> 被拒绝的请求可以降级到 Opus、Sonnet 或其他模型。</p></li><li><p><strong>不能关闭 thinking</strong><code>thinking: {&quot;type&quot;: &quot;disabled&quot;}</code> 在 Fable 5 / Mythos 5 上不支持，可能返回 400。</p></li><li><p><strong>Token 统计可能变多</strong> Fable 5 使用 Claude Opus 4.7 引入的新 tokenizer，同样文本相比旧模型可能产生更多 token。</p></li><li><p><strong>不支持零数据保留</strong> 官方说明 Fable 5 和 Mythos 5 有 30 天数据保留要求，不适用于 Zero Data Retention 场景。</p></li></ol><h2 id="适合什么场景" tabindex="-1">适合什么场景？ <a class="header-anchor" href="#适合什么场景" aria-label="Permalink to &quot;适合什么场景？&quot;">​</a></h2><p>Claude Fable 5 更适合：</p><ul><li>大型代码库理解与重构</li><li>Claude Code 长周期开发任务</li><li>多步骤 Agent 工作流</li><li>深度研究和复杂分析</li><li>长文档阅读与综合</li><li>高价值商业决策分析</li><li>需要 1M 上下文的大型任务</li></ul><p>不太建议用于：</p><ul><li>简单问答</li><li>高频低价值请求</li><li>成本敏感型批量任务</li><li>容易触发安全限制的网络安全、生物等敏感内容</li><li>必须 Zero Data Retention 的企业场景</li></ul><h2 id="和-opus-4-8-怎么选" tabindex="-1">和 Opus 4.8 怎么选？ <a class="header-anchor" href="#和-opus-4-8-怎么选" aria-label="Permalink to &quot;和 Opus 4.8 怎么选？&quot;">​</a></h2><p>如果只是日常写作、普通代码、常规问答，Claude Opus 4.8 仍然是更均衡的选择。</p><p>如果任务很复杂，需要模型长时间保持目标、处理大量上下文、完成多步骤工程或 Agent 工作流，可以考虑 Claude Fable 5。</p><p>简单建议：</p><table tabindex="0"><thead><tr><th>场景</th><th>推荐</th></tr></thead><tbody><tr><td>普通问答、写作、轻量代码</td><td>Opus 4.8 / Sonnet</td></tr><tr><td>复杂代码、长任务 Agent</td><td>Fable 5</td></tr><tr><td>成本敏感请求</td><td>Sonnet / Haiku</td></tr><tr><td>超长上下文复杂任务</td><td>Fable 5</td></tr><tr><td>敏感安全/生物领域研究</td><td>谨慎使用，可能触发拒绝</td></tr></tbody></table><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>Claude Fable 5 是 Anthropic 当前最重要的新模型之一。它不是简单的“更强 Opus”，而是更偏向长周期 Agent、复杂工程、深度推理的新一代模型。</p><p>它的核心价值在于：</p><ul><li>更强的复杂任务处理能力</li><li>1M 上下文</li><li>适合 Claude Code 和 Agent 工作流</li><li>公开可用，但带有更严格安全限制</li></ul><p>对于普通用户来说，Fable 5 适合在“任务足够复杂、价值足够高”的时候使用；对于开发者来说，接入时要重点处理 refusal、fallback、thinking 参数和成本控制。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li><a href="https://www.anthropic.com/news/claude-fable-5-mythos-5" target="_blank" rel="noreferrer">Anthropic：Claude Fable 5 and Claude Mythos 5</a></li><li><a href="https://platform.claude.com/docs/en/about-claude/models/introducing-claude-fable-5-and-claude-mythos-5" target="_blank" rel="noreferrer">Claude API Docs：Introducing Claude Fable 5 and Claude Mythos 5</a></li><li><a href="https://platform.claude.com/docs/en/about-claude/models/overview" target="_blank" rel="noreferrer">Claude API Docs：Models overview</a></li><li><a href="https://platform.claude.com/docs/en/about-claude/pricing" target="_blank" rel="noreferrer">Claude API Docs：Pricing</a></li><li><a href="https://platform.claude.com/docs/en/release-notes/overview" target="_blank" rel="noreferrer">Claude API Release Notes</a></li></ul>',51)])])}const b=a(i,[["render",n]]);export{c as __pageData,b as default};
